# GENERATED by scripts/ops/wavegen.py from /home/rickybao/projects/dreamerv3/ops/waves/a2_scarecrow/spec.yaml -- do not edit by hand.
# Bundle this wave for transfer to the analysis machine.
set -euo pipefail
HERE="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
DV3OPS_ROOT="${DV3OPS_ROOT:-/home/rickybao/projects/dreamerv3}"
[ -f "$DV3OPS_ROOT/scripts/ops/lib/common.sh" ] || {
  echo "ERROR: repo not found at DV3OPS_ROOT=$DV3OPS_ROOT" >&2
  echo "       (set DV3OPS_ROOT if the repo lives elsewhere on this machine)" >&2
  exit 2; }
source "$DV3OPS_ROOT/scripts/ops/lib/common.sh"

bundle="$RUNROOT/bundles/a2_scarecrow_$(date +%Y%m%d_%H%M%S)"
mkdir -p "$bundle/runroot" "$bundle/_cloud_logs"

# COMPLETION.txt is written by the same checker that gates the read, so the
# bundle cannot claim a completeness its own predicates would reject.
python3 "$DV3OPS_ROOT/scripts/ops/wavecheck.py" \
  "$DV3OPS_ROOT/ops/waves/a2_scarecrow" --runroot "$RUNROOT" \
  > "$bundle/COMPLETION.txt" || true
cat "$bundle/COMPLETION.txt"

# Outputs may be directories (fits, adapts) or loose files in a shared folder
# (probe/E4), so preserve the relative path rather than flattening into runroot/.
for run in sc_ctrl_s76 sc_ctrl_s77 sc_ctrl_s78 sc_ctrl_s79 sc_pen1_s88 sc_pen1_s89 sc_pen1_s90 sc_pen1_s91 sc_pen2_s92 sc_pen2_s93 sc_pen2_s94 sc_pen2_s95 sc_scare2_s84 sc_scare2_s85 sc_scare2_s86 sc_scare2_s87 sc_scare_s80 sc_scare_s81 sc_scare_s82 sc_scare_s83; do
  if [ -e "$RUNROOT/$run" ]; then
    mkdir -p "$bundle/runroot/$(dirname "$run")"
    cp -al "$RUNROOT/$run" "$bundle/runroot/$run" 2>/dev/null       || cp -a "$RUNROOT/$run" "$bundle/runroot/$run"
  else
    echo "WARN: missing output $run" >&2
  fi
done

shopt -s nullglob
for pat in 'sc_*.out'; do
  [ -n "$pat" ] || continue
  for f in "$RUNROOT"/_cloud_logs/$pat; do cp -a "$f" "$bundle/_cloud_logs/"; done
done

cp -a "$HERE/runs.json" "$HERE/RUN_IDS.txt" "$bundle/" 2>/dev/null || true
"$DV3OPS_ROOT/scripts/bundle_manifest.sh" generate "$bundle"
echo "$bundle"
